Translate("ptBR", "felwood", {
	title = "Selva Maleva",
	sections = {
		{
			title = "Resumo",
			text = [=[A Selva Maleva é uma floresta moribunda no norte de {link:kalimdor}Kalimdor{/link}, entre o {link:ashenvale}Vale Gris{/link} ao sul e as neves de {link:winterspring}Hibérnia{/link} a nordeste. Suas árvores são negras e retorcidas, seus riachos correm verdes e imundos, e seu ar cheira a podridão e fumaça. Outrora foi o extremo norte da grande floresta dos elfos noturnos. Agora é a ferida que a {link:burning-legion}Legião Ardente{/link} deixou para trás quando foi expulsa do mundo. As feras da Selva Maleva são loucas, seus pelursos são selvagens, e demônios ainda andam por suas depressões. Ainda assim, alguns druidas permanecem em suas clareiras do sul, e não desistiram dela.]=],
		},
		{
			title = "Origens",
			text = [=[A floresta foi um lar dos {link:night-elves}elfos noturnos{/link} por eras sem conta. Seus poços lunares e tocas-túmulo estão espalhados por ela, e as pedras brancas das {link:ruins-of-constellas}Ruínas de Constellas{/link} ainda se erguem em suas clareiras do oeste. Os anciãos arbóreos que guardavam os kaldorei faziam seus lares entre suas árvores. Na {link:third-war}Terceira Guerra{/link}, a Legião veio a {link:kalimdor}Kalimdor{/link}. O senhor do medo {link:tichondrius}Tichondrius{/link} levou para a floresta o Crânio de {link:gul-dan}Gul'dan{/link}, uma relíquia inchada de poder demoníaco, e por meio dele derramou corrupção na terra. Infernais caíram em chamas do céu e deixaram crateras que ainda supuram. Quando {link:illidan-stormrage}Illidan Stormrage{/link} tomou para si o poder do crânio e matou o senhor do medo, o estrago já estava feito. A floresta que sobreviveu era uma floresta vil, e o povo passou a chamá-la de Selva Maleva.]=],
		},
		{
			title = "O Presente",
			text = [=[A Selva Maleva não pertence a ninguém, e muitos poderes a disputam. No sul, os druidas do {link:emerald-circle}Círculo Esmeralda{/link} mantêm um pequeno acampamento chamado {link:emerald-sanctuary}Santuário Esmeralda{/link}, onde estudam a doença e buscam sua cura. A {link:horde}Horda{/link} ocupa {link:bloodvenom-post}Posto Peçonha{/link}, no oeste, e a {link:alliance}Aliança{/link} mantém um poleiro de hipogrifos em {link:talonbranch-glade}Clareira da Galhaça{/link}, no nordeste. Entre eles está o inimigo. Os bruxos do {link:shadow-council}Conselho das Sombras{/link} fizeram de {link:jaedenar}Jaedenar{/link} a sede de sua ordem, e ali negociam com demônios. {link:satyrs}Sátiros{/link} Flamejade conspurcam os velhos poços lunares. Os {link:furbolgs}pelursos{/link} {link:deadwood-furbolgs}Lenha Morta{/link} enlouqueceram. No extremo norte, os pelursos {link:timbermaw-furbolgs}Presamatos{/link} guardam a passagem para {link:winterspring}Hibérnia{/link} e quase não confiam em ninguém. A mácula não fica na Selva Maleva: os druidas da {link:darkshore}Costa Negra{/link} temem que ela esteja escorrendo para oeste, para suas próprias florestas.]=],
		},
		{
			title = "Habitantes",
			text = [=[• {b}O {link:emerald-circle}Círculo Esmeralda{/link}.{/b} Druidas do {link:cenarion-circle}Círculo Cenariano{/link}, tanto da {link:alliance}Aliança{/link} quanto da {link:horde}Horda{/link}, que juraram curar a floresta.
• {b}O {link:shadow-council}Conselho das Sombras{/link}.{/b} Bruxos e cultistas que ocupam {link:jaedenar}Jaedenar{/link} com demônios da Legião ao seu lado.
• {b}Os sátiros Flamejade.{/b} Assombram as {link:ruins-of-constellas}Ruínas de Constellas{/link}, a {link:jadefire-glen}Grota Flamejade{/link} e a {link:jadefire-run}Aldeia Flamejade{/link}, e espalham corrupção por onde passam.
• {b}Os pelursos {link:deadwood-furbolgs}Lenha Morta{/link}.{/b} Uma tribo enlouquecida pela energia vil, com aldeias no extremo sul e no extremo norte da floresta.
• {b}Os pelursos {link:timbermaw-furbolgs}Presamatos{/link}.{/b} A única tribo que manteve a razão, guardando os túneis do {link:timbermaw-hold}Domínio dos Presamatos{/link}.
• {b}A natureza corrompida.{/b} Elementais Warpwood, treants arruinados, gosmas, ursos, lobos e feras-coruja enlouquecidos, e infernais que ainda andam pelo {link:shatter-scar-vale}Vale das Escaras Pungentes{/link}.]=],
		},
		{
			title = "História",
			text = [=[• {b}A Floresta Kaldorei.{/b} Por milênios, os bosques do norte foram uma terra tranquila de poços lunares, tocas-túmulo e anciãos.
• {b}A {link:third-war}Terceira Guerra{/link}.{/b} A hoste da Legião marchou sobre o {link:mount-hyjal}Monte Hyjal{/link}. {link:tichondrius}Tichondrius{/link} corrompeu a floresta com o {link:skull-of-gul-dan}Crânio de Gul'dan{/link}, e infernais foram chamados a cair sobre ela.
• {b}A Escolha de {link:illidan-stormrage}Illidan{/link}.{/b} Illidan Stormrage consumiu o crânio, assumiu a forma de um demônio e matou Tichondrius nestes bosques. Seu irmão o baniu por isso.
• {b}O Presente.{/b} A hoste da Legião foi rompida na {link:battle-of-mount-hyjal}Batalha do Monte Hyjal{/link}, mas {link:stranglethorn-vale}a Selva{/link} Maleva não se curou. Demônios, sátiros e bruxos permanecem, e apenas um punhado de druidas se opõe a eles.]=],
		},
		{
			title = "Lendas da Floresta",
			text = [=[• Os druidas do {link:emerald-circle}Círculo Esmeralda{/link} aprenderam a fazer um unguento que devolve a saúde a uma planta corrompida. Flores-canção, flores-do-vento, raízes-chicote e flores-de-dragão-noturno que se julgavam perdidas voltaram a florescer sob seus cuidados.
• Uma flauta entalhada da madeira de um ancião caído foi encontrada nas mãos de um {link:satyrs}sátiro{/link}. O espírito do ancião estava preso dentro dela e não pôde descansar até que as águas do {link:temple-of-the-moon}Templo da Lua{/link} o libertassem.
• O {link:shadow-council}Conselho das Sombras{/link} guarda sua fortaleza com quatro braseiros cujos nomes são Dor, Malícia, Sofrimento e Ódio.
• Os espíritos de três anciãos, {link:vartrus-the-ancient}Vartrus{/link}, Stoma e Hastat, ainda respondem a quem vem até certa rocha na {link:irontree-woods}Floresta Ferrárbol{/link}.]=],
		},
	},
})

Translate("ptBR", "emerald-sanctuary", {
	title = "Santuário Esmeralda",
	sections = {
		{
			title = "Resumo",
			text = [=[O Santuário Esmeralda é um pequeno acampamento de druidas no sul da {link:felwood}Selva Maleva{/link}, perto da fronteira do {link:ashenvale}Vale Gris{/link}. É o lar do {link:emerald-circle}Círculo Esmeralda{/link}. Aqui, druidas dos elfos noturnos e dos taurens trabalham lado a lado, sejam quais forem as brigas de seus povos em outros lugares. Recolhem amostras de todas as coisas maculadas que a floresta produz e buscam os meios de purificá-las. Amigos de qualquer lado são bem-vindos ali. Ao redor, a floresta é escura e hostil, e sátiros Flamejade espreitam na grota vizinha.]=],
		},
	},
})

Translate("ptBR", "bloodvenom-post", {
	title = "Posto Peçonha",
	sections = {
		{
			title = "Resumo",
			text = [=[Posto Peçonha é o ponto de apoio da {link:horde}Horda{/link} no oeste da {link:felwood}Selva Maleva{/link}, um acampamento de tendas e paliçadas na borda dos bosques corrompidos. {link:orcs}Orcs{/link} de {link:orgrimmar}Orgrimmar{/link} e {link:forsaken}Renegados{/link} da {link:undercity}Cidade Baixa{/link} dividem suas fogueiras. É um posto duro numa terra hostil. Seus guerreiros combateram o {link:shadow-council}Conselho das Sombras{/link} e os pelursos loucos da floresta, e alguns não voltaram. Seus agentes olham mais longe: um estuda os poços lunares corrompidos dos sátiros, e outro os wildkin de {link:winterspring}Hibérnia{/link}. Um mestre de serpes mantém o posto em contato com o resto da Horda.]=],
		},
	},
})

Translate("ptBR", "talonbranch-glade", {
	title = "Clareira da Galhaça",
	sections = {
		{
			title = "Resumo",
			text = [=[Clareira da Galhaça é um pequeno acampamento de elfos noturnos no nordeste da {link:felwood}Selva Maleva{/link}. Hipogrifos se empoleiram em suas árvores e levam mensagens e viajantes ao resto da {link:alliance}Aliança{/link}. Alguns {link:night-elves}kaldorei{/link} o mantêm: um comerciante, um armeiro e os mestres que treinam druidas e caçadores para a longa guerra contra a corrupção. É um lugar para descansar antes da estrada para o norte, e um dos últimos postos avançados dos elfos noturnos na floresta que um dia foi toda deles.]=],
		},
	},
})

Translate("ptBR", "jaedenar", {
	title = "Jaedenar",
	aliases = { "Fortaleza do Conselho das Sombras" },
	sections = {
		{
			title = "Resumo",
			text = [=[Jaedenar fica no oeste da {link:felwood}Selva Maleva{/link}, descendo por um caminho a partir da estrada principal. Foi outrora um lugar dos elfos noturnos, com um poço lunar em seu coração e tocas-túmulo por baixo. Agora é a sede do {link:shadow-council}Conselho das Sombras{/link}. Cultistas, bruxos e seus cães ocupam a superfície, e o poço lunar se tornou imundo. Abaixo fica a Fortaleza do Conselho das Sombras, onde demônios da Legião andam abertamente. Suas câmaras são guardadas por quatro braseiros de proteção. Em seu ponto mais profundo, um senhor do medo mantém sua corte, e os bruxos que o servem fazem seus pactos no escuro.]=],
		},
	},
})

Translate("ptBR", "irontree-woods", {
	title = "Floresta Ferrárbol",
	aliases = { "Caverna Ferrárbol" },
	sections = {
		{
			title = "Resumo",
			text = [=[A Floresta Ferrárbol é o coração norte da {link:felwood}Selva Maleva{/link}, uma extensão de árvores arruinadas e ruínas. Treants andavam aqui outrora como guardiões da floresta. A corrupção os retorceu, e os que restam vagam e pisoteiam entre as árvores mortas. Na Caverna Ferrárbol, os elementais Warpwood caíram tão baixo que os druidas já não esperam purificá-los. Ainda assim, a floresta não está de todo perdida. Nas ruínas de sua parte sul, o espírito de uma anciã chamada {link:arei}Arei{/link} permanece, e os espíritos de três outros anciãos ainda respondem junto a uma pedra entre as árvores.]=],
		},
	},
})

Translate("ptBR", "shatter-scar-vale", {
	title = "Vale das Escaras Pungentes",
	sections = {
		{
			title = "Resumo",
			text = [=[O Vale das Escaras Pungentes fica a leste da estrada, no centro da {link:felwood}Selva Maleva{/link}. Na {link:third-war}Terceira Guerra{/link}, a Legião fez seus infernais caírem sobre este vale, e as crateras que eles abriram ainda marcam o chão. Água verde e imunda se acumulou nas covas e nunca clareou. Infernais ainda andam entre elas, sem mente e destrutivos, com elementais de pura entropia ao seu lado. Os druidas esperavam encontrar uma fonte limpa na Selva Maleva. Não a encontraram aqui. Em algum lugar do vale jazem os restos apagados do infernal {link:kroshius}Kroshius{/link}.]=],
		},
	},
})

Translate("ptBR", "ruins-of-constellas", {
	title = "Ruínas de Constellas",
	aliases = { "Constellas" },
	sections = {
		{
			title = "Resumo",
			text = [=[As Ruínas de Constellas ficam no sudoeste da {link:felwood}Selva Maleva{/link}. Foram uma cidade dos elfos noturnos, e em seu coração há um poço lunar que já foi um símbolo de renovação. Os sátiros Flamejade fizeram das ruínas seu lar, e o poço lunar agora transborda de corrupção. Suas águas são usadas para gerar mais sátiros, e uma fera que bebe delas fica maior, mais forte e completamente vil. O {link:satyrs}sátiro{/link} {link:xavathras}Xavathras{/link} governava aqui, e seu trabalho alimentava os planos de outro sátiro no norte.]=],
		},
	},
})

Translate("ptBR", "jadefire-glen", {
	title = "Grota Flamejade",
	sections = {
		{
			title = "Resumo",
			text = [=[A Grota Flamejade é uma depressão escura no sul da {link:felwood}Selva Maleva{/link}, perto do {link:emerald-sanctuary}Santuário Esmeralda{/link}. Seu nome vem dos {link:satyrs}sátiros{/link} Flamejade, que a ocupam. Seus juramentados vis e ladinos se reúnem aqui para espalhar a corrupção entre as feras do sul da floresta. Os druidas do santuário vivem com os sátiros quase à sua porta, e contam a grota entre os primeiros lugares que precisam ser purificados se a floresta um dia for curada.]=],
		},
	},
})

Translate("ptBR", "jadefire-run", {
	title = "Aldeia Flamejade",
	sections = {
		{
			title = "Resumo",
			text = [=[A Aldeia Flamejade fica no noroeste da {link:felwood}Selva Maleva{/link}. É o segundo acampamento dos sátiros Flamejade, e o mais perigoso. Clamadores infernais, traidores e trapaceiros se reúnem aqui sob o {link:satyrs}sátiro{/link} {link:xavaric}Xavaric{/link}, que recebia os frutos do poço lunar corrompido de {link:ruins-of-constellas}Constellas{/link}. Os sátiros da Aldeia se alimentam da corrupção das criaturas da floresta. Entre eles foi encontrada uma flauta de madeira entalhada de um ancião caído, e ela revelou aos druidas que a crueldade dos sátiros alcançava até os protetores da floresta.]=],
		},
	},
})

Translate("ptBR", "deadwood-village", {
	title = "Vila da Lenha Morta",
	sections = {
		{
			title = "Resumo",
			text = [=[A Vila da Lenha Morta é uma aldeia de pelursos no extremo sul da {link:felwood}Selva Maleva{/link}, perto da fronteira do {link:ashenvale}Vale Gris{/link}. Pertence à {link:deadwood-furbolgs}tribo Lenha Morta{/link}, que a energia vil enlouqueceu. Guerreiros, desbravadores e jardineiros guardam suas cabanas, e seu suserano, {link:overlord-ror}Ror{/link}, é um grande {link:furbolgs}pelurso{/link} conspurcado de força terrível. O pelurso {link:timbermaw-furbolgs}Presamatos{/link} {link:grazle}Grazle{/link} vigia a aldeia de perto e pede aos que querem ser amigos de sua tribo que reduzam seus números.]=],
		},
	},
})

Translate("ptBR", "felpaw-village", {
	title = "Aldeia Patavil",
	sections = {
		{
			title = "Resumo",
			text = [=[A Aldeia Patavil é o acampamento do norte dos pelursos {link:deadwood-furbolgs}Lenha Morta{/link}, nas colinas abaixo da entrada do {link:timbermaw-hold}Domínio dos Presamatos{/link}. {link:the-night-watch}Vigias{/link} de toca, vingadores e xamãs vivem aqui sob o Chefe Bloodmaw. Os {link:timbermaw-furbolgs}Presamatos{/link} que guardam o Domínio olham para ela com tristeza, pois seu povo é seu próprio irmão. Em seu acampamento há um caldeirão de uma bebida verde e fedorenta. {link:furbolgs}Pelursos{/link} Winterfall, das neves além, foram vistos passando pelo Domínio, e alguns desconfiam que a bebida é levada ao norte para eles.]=],
		},
	},
})

Translate("ptBR", "timbermaw-hold", {
	title = "Domínio dos Presamatos",
	sections = {
		{
			title = "Resumo",
			text = [=[O Domínio dos Presamatos é o lar dos pelursos {link:timbermaw-furbolgs}Presamatos{/link}, uma rede de túneis nas montanhas da borda norte da {link:felwood}Selva Maleva{/link}. Suas passagens atravessam a rocha até {link:winterspring}Hibérnia{/link} e são a única estrada para o norte. Os pelursos as guardam com ferocidade. Estranhos que não conquistaram sua confiança são recebidos com lanças, e matar um Presamatos, mesmo em defesa própria, é ser contado entre seus inimigos. Lá dentro, seus anciãos, místicos e comerciantes mantêm a vida da tribo, e estudam a corrupção que tomou seus parentes.]=],
		},
	},
})

Translate("ptBR", "eridan-bluewind", {
	title = "Eridan Bluewind",
	subtitle = "Druida do Círculo Esmeralda",
	found = "O Santuário Esmeralda, no sul da Selva Maleva",
	hint = [=[Procure a druida do Círculo Esmeralda que sente o sofrimento dos anciãos.]=],
	allegiance = "Círculo Esmeralda · Círculo Cenariano",
	aliases = { "Eridan" },
	sections = {
		{
			title = "Resumo",
			text = [=[Eridan Bluewind é uma druida do {link:emerald-circle}Círculo Esmeralda{/link} que vive no {link:emerald-sanctuary}Santuário Esmeralda{/link}. Ela se entregou à cura da {link:felwood}Selva Maleva{/link}, e carrega consigo sua dor. Grande parte de seu trabalho é guerra. Ela manda aliados contra os sátiros Flamejade que espalham a corrupção, e gasta suas próprias forças tentando desfazer o que eles fizeram.]=],
		},
		{
			title = "Importância",
			text = [=[Eridan foi a primeira do {link:emerald-circle}Círculo Esmeralda{/link} a ver que os sátiros da {link:felwood}Selva Maleva{/link} não eram apenas cruéis, mas organizados. O acampamento de {link:xavathras}Xavathras{/link} no sul, ela descobriu, cuidava de um poço lunar corrompido em benefício de {link:xavaric}Xavaric{/link} no norte. Ela desconfia que algo ainda maior está por trás deles. Seu saber vai também muito além da Selva Maleva: viajantes a procuram por segredos dos elementos que poucos outros conhecem.]=],
		},
		{
			title = "Feitos",
			text = [=[• Mandou combatentes contra {link:xavathras}Xavathras{/link} nas {link:ruins-of-constellas}Ruínas de Constellas{/link} e contra {link:xavaric}Xavaric{/link} na {link:jadefire-run}Aldeia Flamejade{/link}.
• Libertou o espírito de um ancião que os sátiros haviam prendido numa flauta.
• Ensinou a fazer um totem capaz de romper a aura do elemental de fogo {link:blazerunner}Blazerunner{/link}, na {link:un-goro-crater}Cratera Un'Goro{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Os Flamejade",
			hint = "Abata os senhores sátiros dos Flamejade.",
			text = [=[Quando {link:xavathras}Xavathras{/link} caiu, Eridan não se alegrou. Ela sentira que o {link:satyrs}sátiro{/link} era apenas uma parte de um plano maior. A verdade veio devagar: Xavathras cultivara um poço lunar corrompido e mandava seus frutos para o norte, a {link:xavaric}Xavaric{/link}. Com os dois mortos, ela rezou para que Eluna protegesse os que tinham feito o trabalho. A cura, ela sabia, levaria muito mais tempo que a matança.]=],
		},
		{
			title = "O Ancião Aprisionado",
			hint = [=[Leve à druida a flauta encontrada com um sátiro e a água abençoada do Templo da Lua.]=],
			text = [=[A flauta de {link:xavaric}Xavaric{/link} fora entalhada de um dos anciãos arbóreos que guardavam os elfos noturnos. Por magia vil, o espírito do ancião fora preso à madeira e torturado ali. Eridan mal conseguia segurá-la. Ela a lavou na água abençoada de Eluna, e o elo se rompeu. Acreditava que a flauta, tocada num lugar sagrado, poderia chamar os espíritos dos anciãos que ainda assombram a floresta.]=],
		},
		{
			title = "A Missão de um Estranho",
			hint = "Venha até Eridan em nome de um errante da Cratera Un'Goro.",
			text = [=[Um estranho na {link:un-goro-crater}Cratera Un'Goro{/link} dissera o nome dela quando mal se lembrava de qualquer outra coisa. Eridan não o conhecia, mas conhecia seu propósito. Reuniu garras e o coração de um treant de Ferrárbol, e os mandou com o Livro de Aquor a um círculo de pedras em {link:tanaris}Tanaris{/link}, onde o elemental da água Aquementas podia ser chamado para forjá-los num totem.]=],
		},
	},
	mentions = {
		{ text = "A Flauta de {link:xavaric}Xavaric{/link}" },
		{ text = "A Memória de {link:linken}Linken{/link}" },
		{ text = "Coração de Prata" },
		{ text = "Aquementas" },
		{ text = "A Corrupção dos Flamejade" },
		{ text = "Anciãos Presos pela Energia Vil" },
		{ text = "Purificado!" },
		{ text = "Mais Corrupção" },
	},
	bonds = {
		{ id = "xavathras", name = "Xavathras", note = "o sátiro que ela mandou matar" },
		{ id = "xavaric", name = "Xavaric", note = "o senhor sátiro do norte" },
		{ id = "arei", name = "Arei", note = "um espírito ancião da floresta" },
		{ id = "greta-mosshoof", name = "Greta Mosshoof", note = "do mesmo círculo" },
	},
})

Translate("ptBR", "greta-mosshoof", {
	title = "Greta Mosshoof",
	subtitle = "Druida do Círculo Esmeralda",
	found = "O Santuário Esmeralda, no sul da Selva Maleva",
	hint = [=[Procure a druida do Círculo Esmeralda que trava guerra contra o Conselho das Sombras.]=],
	allegiance = "Círculo Esmeralda · Círculo Cenariano",
	aliases = { "Greta" },
	sections = {
		{
			title = "Resumo",
			text = [=[Greta Mosshoof é uma druida do {link:emerald-circle}Círculo Esmeralda{/link}, e reza para a Mãe Terra. Enquanto outros de seu círculo buscam curar a floresta, ela assumiu a tarefa de atacar a causa de sua doença. Sua inimiga é o {link:shadow-council}Conselho das Sombras{/link} em {link:jaedenar}Jaedenar{/link}, e ela pretende cortar sua cabeça.]=],
		},
		{
			title = "Importância",
			text = [=[Greta é quem planeja a guerra do Círculo contra {link:jaedenar}Jaedenar{/link}. Ela entende que {link:shadow-council}o Concílio{/link} não pode ser combatido às cegas, e tem paciência para aprender antes de atacar. É também a guardiã de uma esperança maior: a reunião de uma cura que um dia poderá sanar as árvores e as criaturas da {link:felwood}Selva Maleva{/link}.]=],
		},
		{
			title = "Feitos",
			text = [=[• Pôs à prova a determinação dos que vieram ajudá-la contra os cultistas de {link:jaedenar}Jaedenar{/link}.
• Fez os espíritos da água purificarem a água corrompida do poço lunar de Jaedenar.
• Perscrutou a Fortaleza do Conselho das Sombras e descobriu quem liderava {link:shadow-council}o Concílio{/link}.
• Mandou seus aliados contra o {link:shadow-lord-fel-dan}Senhor das Sombras Fel'dan{/link} e seus servos.
• Buscou o sangue do draco verde {link:morphaz}Morphaz{/link} para a segunda cura da {link:felwood}Selva Maleva{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Água Contra Fogo",
			hint = [=[Leve a água do poço lunar de Jaedenar para ser purificada, e use-a nos braseiros da Fortaleza do Conselho das Sombras.]=],
			text = [=[O Concílio protegia sua fortaleza com feitiços que ardiam em quatro braseiros. Greta mandou buscar água do poço lunar corrompido no coração de {link:jaedenar}Jaedenar{/link}, e depois a mandou ao sul, a uma velha amiga, uma xamã que vive junto ao mar ao sul de {link:ratchet}Vila Catraca{/link}. Os espíritos da água ouviram a xamã e abençoaram a causa. Com a água purificada, as chamas foram apagadas. Por um curto tempo, antes que os bruxos renovassem suas proteções, Greta pôde ver dentro da fortaleza.]=],
		},
		{
			title = "A Cabeça da Serpente",
			hint = "Ataque o mortal que lidera o Conselho das Sombras.",
			text = [=[O que Greta viu lhe disse que não havia um jeito astuto de entrar. {link:shadow-lord-fel-dan}Fel'dan{/link}, o Senhor das Sombras, era o mortal no comando lá embaixo, e era ele quem fazia os pactos com a Legião. Ela mandou seus aliados direto até ele. Quando a cabeça dele voltou para ela, louvou a Mãe Terra. Esperava que, sem ele, {link:shadow-council}o Concílio{/link} se voltasse contra si mesmo.]=],
		},
		{
			title = "A Segunda Cura",
			hint = "Traga-lhe o sangue do draco Morphaz, do templo submerso.",
			text = [=[Dizem que o draco verde {link:morphaz}Morphaz{/link} é imune a todo veneno e doença, e muitos druidas morreram para descobrir isso. Greta queria seu sangue. Quando ele chegou, ela mal pôde acreditar. Levaria uma vida inteira, disse, para desfazer o que acontecera na {link:felwood}Selva Maleva{/link}, mas enfim o Círculo tinha os meios para começar.]=],
		},
	},
	mentions = {
		{ text = "Forças de {link:jaedenar}Jaedenar{/link}" },
		{ text = "Coleta da Água Corrompida" },
		{ text = "Em Busca de Ajuda Espiritual" },
		{ text = "Água Purificada Volta à {link:felwood}Selva Maleva{/link}" },
		{ text = "Apagando as Chamas da Proteção" },
		{ text = "Um Golpe Final" },
		{ text = "Sangue de {link:morphaz}Morphaz{/link}" },
	},
	bonds = {
		{ id = "shadow-lord-fel-dan", name = "Senhor das Sombras Fel'dan", note = "a cabeça da serpente" },
		{ id = "eridan-bluewind", name = "Eridan Bluewind", note = "do mesmo círculo" },
		{ id = "morphaz", name = "Morphaz", note = "cujo sangue ela buscou" },
	},
})

Translate("ptBR", "lord-banehollow", {
	title = "Lorde Banehollow",
	subtitle = "Senhor do Medo de Jaedenar",
	found = [=[As profundezas da Fortaleza do Conselho das Sombras, em Jaedenar]=],
	hint = [=[Envolva-se em sombras e procure o senhor do medo no fundo de Jaedenar.]=],
	allegiance = "Legião Ardente · Conselho das Sombras",
	aliases = { "Banehollow" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Lorde Banehollow é um senhor do medo que mantém sua corte nas profundezas de {link:jaedenar}Jaedenar{/link}, a sede do {link:shadow-council}Conselho das Sombras{/link}. É velho, paciente e cruel. Os bruxos do Concílio vêm e vão diante dele, e só os que vestem a própria sombra do Concílio podem se aproximar dele ilesos.]=],
		},
		{
			title = "Importância",
			text = [=[Banehollow é o demônio por trás dos bruxos mortais de {link:jaedenar}Jaedenar{/link}, e tem rivais até entre os de sua espécie. O principal deles é o Lorde Hel'nurath, que governa um domínio chamado Xoroth além deste mundo e ali cria os famosos corcéis do medo. Banehollow guarda um estoque de poeira estelar de Xoroth, e os bruxos que desejam abrir um caminho para aquele reino precisam negociá-la com ele.]=],
		},
		{
			title = "Feitos",
			text = [=[• Governa das profundezas da {link:jaedenar}Fortaleza do Conselho das Sombras{/link}.
• Desmascarou seu servo {link:ulathek}Ulathek{/link} como espião de Hel'nurath.
• Vende a poeira estelar de Xoroth por meio de seu servo Ur'dan.]=],
		},
		{
			title = "Não Registrado",
			text = [=[Nenhuma crônica registra há quanto tempo Banehollow habita {link:stranglethorn-vale}a Selva{/link} Maleva, nem que acordo o liga ao {link:shadow-council}Conselho das Sombras{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Um Hóspede em Jaedenar",
			hint = [=[Venha a Jaedenar disfarçado pelas poções sombrias das Estepes Ardentes.]=],
			text = [=[O goblin {link:gorzeeki-wildeyes}Gorzeeki Wildeyes{/link} prepara poções que deixam quem as bebe passar por um membro do {link:shadow-council}Conselho das Sombras{/link}. Os que as bebem podem andar por {link:jaedenar}Jaedenar{/link} e ficar diante de Banehollow. Ele não os recebe com calor. Sua paciência, diz ele, se estende por milênios, e ainda assim eles não terão mais que um instante dela.]=],
		},
		{
			title = "O Coração do Traidor",
			hint = "Prove seu serviço ao senhor do medo.",
			text = [=[{link:ulathek}Ulathek{/link} rastejava diante de seu senhor enquanto tramava com Hel'nurath, que esperava tomar o poder de Banehollow na {link:felwood}Selva Maleva{/link}. Banehollow sabia. Queria que Ulathek fosse informado disso, e queria ver o medo. Depois queria o coração, que pretendia deixar apodrecer por uma semana antes de comê-lo.]=],
		},
		{
			title = "Poeira Estelar de Xoroth",
			hint = [=[Compre a poeira estelar de Xoroth do servo do senhor do medo.]=],
			text = [=[Banehollow adivinhou de imediato por que um bruxo queria poeira estelar: para abrir um portal ao domínio de seu rival e roubar um de seus corcéis do medo. A ideia não o perturbou. Deixou seu servo Ur'dan vender a poeira estelar, por um preço. Ela voltou a {link:gorzeeki-wildeyes}Gorzeeki{/link} e, dele, a {link:mor-zul-bloodbringer}Mor'zul Bloodbringer{/link}, que precisava dela para sua tinta.]=],
		},
	},
	mentions = {
		{ text = "Lorde Banehollow" },
		{
			text = [=[{link:ulathek}Ulathek{/link}, {link:illidan-stormrage}o Traidor{/link}]=],
		},
		{ text = "{link:the-ruins-of-stardust}Poeira Estelar{/link} Xorothiana" },
	},
	bonds = {
		{ id = "ulathek", name = "Ulathek", note = "seu servo traiçoeiro" },
		{ id = "gorzeeki-wildeyes", name = "Gorzeeki Wildeyes", note = "manda-lhe visitantes" },
		{ id = "mor-zul-bloodbringer", name = "Mor'zul Bloodbringer", note = "recebe sua poeira estelar" },
		{ id = "shadow-lord-fel-dan", name = "Senhor das Sombras Fel'dan", note = "o senhor mortal do Concílio abaixo dele" },
	},
})

Translate("ptBR", "tichondrius", {
	title = "Tichondrius",
	subtitle = "Senhor do Medo da Legião Ardente",
	hint = [=[Descubra quem envenenou a floresta do norte com o Crânio de Gul'dan.]=],
	allegiance = "Legião Ardente",
	sections = {
		{
			title = "Resumo",
			text = [=[Tichondrius foi um senhor do medo, um dos nathrezim que servem a {link:burning-legion}Legião Ardente{/link}. Na {link:third-war}Terceira Guerra{/link}, esteve entre os demônios que guiavam o {link:scourge}Flagelo{/link} em nome da Legião, e dava suas ordens ao cavaleiro da morte {link:arthas-menethil}Arthas Menethil{/link}. Quando a Legião veio a {link:kalimdor}Kalimdor{/link}, ele levou o Crânio de {link:gul-dan}Gul'dan{/link} para a floresta do norte e a envenenou com o poder sombrio do crânio. Essa floresta é {link:stranglethorn-vale}a Selva{/link} Maleva. Ele foi morto ali por {link:illidan-stormrage}Illidan Stormrage{/link}.]=],
		},
		{
			title = "Importância",
			text = [=[De todos os demônios da {link:third-war}Terceira Guerra{/link}, Tichondrius foi o que deixou a marca mais profunda na própria terra. {link:archimonde}Archimonde{/link} caiu no {link:mount-hyjal}Monte Hyjal{/link} e sua hoste foi rompida, mas a corrupção que Tichondrius semeou não morreu com ele. Cada {link:furbolgs}pelurso{/link} louco, cada treant arruinado e cada poço lunar imundo da {link:felwood}Selva Maleva{/link} faz parte de seu legado. Sua morte também mudou {link:illidan-stormrage}Illidan{/link} para sempre: para derrotá-lo, Illidan tomou para si o poder do crânio, e seu povo o baniu por isso.]=],
		},
		{
			title = "O Flagelo e a Legião",
			text = [=[O Lich Rei criou o {link:scourge}Flagelo{/link}, mas não o criou livre. Os senhores do medo da Legião o vigiavam, e Tichondrius estava entre eles. Depois que {link:arthas-menethil}Arthas{/link} matou o pai e se entregou por inteiro ao Flagelo, Tichondrius pôs à prova a lealdade do príncipe e lhe deu suas tarefas. Arthas levou os restos do necromante {link:kel-thuzad}Kel'Thuzad{/link} à Nascente do Sol de {link:quel-thalas}Quel'Thalas{/link}, onde Kel'Thuzad foi erguido como lich. Kel'Thuzad, por sua vez, chamou {link:archimonde}Archimonde{/link} ao mundo em {link:dalaran}Dalaran{/link}. Com o senhor da Legião enfim presente, o Flagelo cumprira seu propósito, e os demônios se voltaram para {link:kalimdor}Kalimdor{/link}.]=],
		},
		{
			title = "O Envenenamento da Floresta",
			text = [=[A hoste de {link:archimonde}Archimonde{/link} marchou sobre o {link:mount-hyjal}Monte Hyjal{/link} e a Árvore do Mundo, {link:nordrassil}Nordrassil{/link}. Tichondrius veio às florestas do norte com o {link:skull-of-gul-dan}Crânio de Gul'dan{/link}, os restos do bruxo que primeiro ligara os orcs à Legião. O crânio ainda guardava muito do poder vil de {link:gul-dan}Gul'dan{/link}, e Tichondrius o usou para corromper os bosques ao seu redor. As árvores escureceram e as águas se estragaram. Feras e pelursos enlouqueceram. Infernais caíram em chamas do céu, e os anciãos que guardavam a floresta foram destruídos.]=],
		},
		{
			title = "A Morte do Senhor do Medo",
			text = [=[{link:tyrande-whisperwind}Tyrande Whisperwind{/link} libertara {link:illidan-stormrage}Illidan{/link} de sua longa prisão para combater os demônios. Illidan soube do crânio e foi atrás dele. Tomou-o e consumiu seu poder. Isso o transformou: nasceram-lhe chifres e grandes asas escuras, e ele próprio se tornou em parte demônio. Com esse poder, matou Tichondrius. A vitória lhe custou todo o resto. {link:malfurion-stormrage}Malfurion Stormrage{/link} não pôde perdoar aquilo em que seu irmão se tornara, e baniu Illidan das florestas dos elfos noturnos.]=],
		},
		{
			title = "Não Registrado",
			text = [=[Nenhuma crônica conta como Tichondrius veio a possuir o crânio, nem quanto tempo habitou a floresta antes que {link:illidan-stormrage}Illidan{/link} o encontrasse.]=],
		},
	},
	chapters = {
		{
			title = "A Memória dos Anciãos",
			hint = [=[Conduza o espírito de uma anciã para fora da floresta corrompida.]=],
			text = [=[O espírito ancião {link:arei}Arei{/link} ainda se lembra da floresta antes da chegada da Legião. Lembra-se dos infernais, da destruição e do caos. Lembra-se de que o {link:skull-of-gul-dan}crânio de Gul'dan{/link} garantiu que nada na floresta fosse poupado. Mesmo como espírito, ela não consegue escapar do sofrimento da terra. Pede apenas para ser conduzida para fora dele, para poder descansar.]=],
		},
	},
	mentions = {
		{ text = "Espírito Ancião" },
	},
	bonds = {
		{ id = "illidan-stormrage", name = "Illidan Stormrage", note = "seu matador" },
		{ id = "gul-dan", name = "Gul'dan", note = "o bruxo cujo crânio ele usou" },
		{ id = "archimonde", name = "Archimonde", note = "seu senhor na Terceira Guerra" },
		{ id = "arthas-menethil", name = "Arthas Menethil", note = "o cavaleiro da morte que ele comandava" },
		{ id = "arei", name = "Arei", note = "uma anciã que se lembra de sua corrupção" },
	},
})

Translate("ptBR", "skull-of-gul-dan", {
	title = "Crânio de Gul'dan",
	aliases = { "crânio de Gul'dan" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Crânio de Gul'dan era o crânio do bruxo {link:orcs}orc{/link} {link:gul-dan}Gul'dan{/link}, fundador do {link:shadow-council}Conselho das Sombras{/link}. Sobreviveu à morte do bruxo na Tumba de {link:sargeras}Sargeras{/link} e manteve muito de seu poder vil. Na {link:third-war}Terceira Guerra{/link}, o senhor do medo {link:tichondrius}Tichondrius{/link} o trouxe a {link:kalimdor}Kalimdor{/link} e o usou para corromper a floresta do norte. {link:illidan-stormrage}Illidan Stormrage{/link} o tomou dele e consumiu seu poder, e com isso se tornou uma criatura meio demônio.]=],
		},
		{
			title = "Seu Legado",
			text = [=[O crânio já não existe, mas sua obra permanece. A floresta que ele envenenou se chama {link:felwood}Selva Maleva{/link}. Os espíritos dos anciãos se lembram de que ele nada poupou, e os druidas do {link:emerald-circle}Círculo Esmeralda{/link} ainda lutam contra o que ele deixou para trás.]=],
		},
	},
})

Translate("ptBR", "shadow-council", {
	title = "Conselho das Sombras",
	aliases = { "o Concílio" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Conselho das Sombras é uma ordem secreta de bruxos que servem a {link:burning-legion}Legião Ardente{/link}. Nasceu entre os orcs de Draenor, e sobreviveu à {link:horde}Horda{/link} que um dia governou. Hoje sua sede é {link:jaedenar}Jaedenar{/link}, na {link:felwood}Selva Maleva{/link}, e suas seitas estão espalhadas pelo mundo.]=],
		},
		{
			title = "Origens",
			text = [=[O senhor demoníaco {link:kil-jaeden}Kil'jaeden{/link} escolheu o bruxo {link:gul-dan}Gul'dan{/link} como seu servo entre os orcs. Gul'dan reuniu os mais ambiciosos de seus colegas bruxos num conselho oculto. Ele governava os clãs orcs por trás de um chefe guerreiro fantoche e os levou a beber o sangue de {link:mannoroth}Mannoroth{/link}. Por meio de Gul'dan, abriu o {link:dark-portal}Portal Negro{/link}.]=],
		},
		{
			title = "A Queda",
			text = [=[Nos dias que se seguiram à {link:first-war}Primeira Guerra{/link}, o Concílio instalou sua sede no {red:blackrock-spire}Pico da Rocha Negra{/red}. {link:orgrim-doomhammer}Orgrim Doomhammer{/link} voltou-se contra ele ali, matou a maior parte de seus membros e fez {link:gul-dan}Gul'dan{/link} prisioneiro. Mais tarde, Gul'dan traiu a {link:horde}Horda{/link} e morreu. Acreditava-se que o Concílio morrera com ele.]=],
		},
		{
			title = "Nos Dias de Hoje",
			text = [=[Não morreu. Em {link:jaedenar}Jaedenar{/link}, o {link:shadow-lord-fel-dan}Senhor das Sombras Fel'dan{/link} lidera a ordem e faz seus pactos com a Legião, enquanto um senhor do medo mantém sua corte nas profundezas abaixo. O Concílio é culpado por muitos males na {link:felwood}Selva Maleva{/link} e além. Sua marca aparece entre os bruxos do {link:arathi-highlands}Planalto Arathi{/link}. Em {link:orgrimmar}Orgrimmar{/link}, a {link:burning-blade}Lâmina Ardente{/link} e a Searing Blade servem a seus propósitos, e os Shadowsworn da {link:blasted-lands}Barreira do Inferno{/link} são seus herdeiros. {link:thrall}Thrall{/link} sabe que ele vive, e pretende encontrá-lo.]=],
		},
	},
})

Translate("ptBR", "emerald-circle", {
	title = "Círculo Esmeralda",
	sections = {
		{
			title = "Resumo",
			text = [=[O Círculo Esmeralda é uma irmandade de druidas do {link:cenarion-circle}Círculo Cenariano{/link} que se dedicaram à {link:felwood}Selva Maleva{/link}. Elfos noturnos e taurens servem juntos nele, e acolhem amigos da {link:alliance}Aliança{/link} e da {link:horde}Horda{/link} da mesma forma. Do {link:emerald-sanctuary}Santuário Esmeralda{/link}, estudam a corrupção e tentam revertê-la.]=],
		},
		{
			title = "Seu Trabalho",
			text = [=[• Combatem os sátiros Flamejade e o {link:shadow-council}Conselho das Sombras{/link}, que espalham e alimentam a corrupção.
• Aprenderam a fazer unguentos que curam plantas corrompidas, mas só compartilham esse saber com quem prova seu valor.
• Buscam água limpa, e uma cura que possa sanar as árvores e as criaturas da floresta.
• Estudam os pelursos da {link:felwood}Selva Maleva{/link} e de além, e a loucura que os tomou.]=],
		},
		{
			title = "Não Registrado",
			text = [=[Nenhuma crônica registra quando o Círculo Esmeralda foi fundado, nem quem o liderou primeiro.]=],
		},
	},
})

Translate("ptBR", "deadwood-furbolgs", {
	title = "Pelursos Lenha Morta",
	aliases = { "Lenha Morta", "tribo Lenha Morta" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os Lenha Morta são uma tribo de {link:furbolgs}pelursos{/link} da {link:felwood}Selva Maleva{/link} enlouquecida pela energia vil. Ocupam a {link:deadwood-village}Vila da Lenha Morta{/link}, no sul da floresta, e a {link:felpaw-village}Aldeia Patavil{/link}, no norte, e atacam todos que se aproximam.]=],
		},
		{
			title = "A Loucura",
			text = [=[Os {link:timbermaw-furbolgs}Presamatos{/link} dizem que os Lenha Morta não são maus por natureza. É a energia vil que polui suas mentes, e isso não pode ser desfeito. Seus totens rituais fedem a decomposição e desespero. Em seu acampamento do norte, uma bebida verde e podre borbulha num caldeirão, e ela talvez esteja espalhando a loucura entre os pelursos Winterfall de {link:winterspring}Hibérnia{/link}.]=],
		},
		{
			title = "Seus Chefes",
			text = [=[• {b}O {link:overlord-ror}Suserano Ror{/link}{/b} governa a {link:deadwood-village}Vila da Lenha Morta{/link}, no sul.
• {b}O Chefe Bloodmaw{/b} governa o acampamento perto do {link:timbermaw-hold}Domínio dos Presamatos{/link}, no norte.]=],
		},
	},
})

Translate("ptBR", "timbermaw-furbolgs", {
	title = "Pelursos Presamatos",
	aliases = { "Presamatos", "tribo Presamatos" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os Presamatos são a única tribo de {link:furbolgs}pelursos{/link} que escapou da corrupção. Habitam o {link:timbermaw-hold}Domínio dos Presamatos{/link}, os túneis entre a {link:felwood}Selva Maleva{/link} e {link:winterspring}Hibérnia{/link}, e os guardam contra todos que chegam.]=],
		},
		{
			title = "Um Povo Desconfiado",
			text = [=[Os Presamatos confiam em muito poucos. Muitos viajantes agora matam qualquer {link:furbolgs}pelurso{/link} que veem, sem perguntar se é amigo ou inimigo. Os Presamatos aprenderam com isso. Só acolhem os que provam seu valor contra as tribos corrompidas, os {link:deadwood-furbolgs}Lenha Morta{/link} da {link:felwood}Selva Maleva{/link} e os Winterfall de {link:winterspring}Hibérnia{/link}. Entristece-os lutar contra seus próprios parentes, mas eles o fazem. O {link:magni-bronzebeard}Rei Magni{/link} de {link:ironforge}Altaforja{/link} e o Chefe Guerreiro da {link:horde}Horda{/link} já tentaram, no passado, se aproximar deles.]=],
		},
		{
			title = "Sua Esperança",
			text = [=[Os Presamatos acreditam que os Winterfall são governados por um demônio. Se ele fosse destruído, a cura dos Winterfall poderia começar, e o Domínio estaria seguro por muitos anos.]=],
		},
	},
})

Translate("ptBR", "arathandris-silversky", {
	title = "Arathandris Silversky",
	subtitle = "Druida do Círculo Esmeralda",
	found = "Uma clareira a leste do Santuário Esmeralda",
	hint = [=[Encontre a druida que guarda o segredo de curar as plantas da Selva Maleva.]=],
	allegiance = "Círculo Esmeralda · Círculo Cenariano",
	aliases = { "Arathandris" },
	sections = {
		{
			title = "Resumo",
